INSERT INTO DimBroker (SK_BrokerID, BrokerID, ManagerID, FirstName, LastName, MiddleInitial, Branch, Office, Phone, IsCurrent, BatchID, EffectiveDate, EndDate) SELECT CAST(EmployeeID AS INT) AS SK_BrokerID, CAST(HR.EmployeeID AS INT) AS BrokerID, CAST(HR.ManagerID AS INT) AS ManagerID, CAST(EmployeeFirstName AS TEXT) AS FirstName, CAST(HR.EmployeeLastName AS TEXT) AS LastName, CAST(NULLIF(EmployeeMI, '') AS TEXT) AS MiddleInitial, CAST(EmployeeBranch AS TEXT) AS Branch, CAST(EmployeeOffice AS TEXT) AS Office, CAST(EmployeePhone AS TEXT) AS Phone, CAST(TRUE AS BOOLEAN) AS IsCurrent, CAST(1 AS INT) AS BatchID, CAST('1970-01-01' AS DATE) AS EffectiveDate, CAST('9999-12-31' AS DATE) AS EndDate FROM Source.HR WHERE EmployeeJobCode = 314;
